/*
====================================================================================================
  CO SO DU LIEU: HE THONG DAT VE XEM PHIM TRUC TUYEN CGV CINEMAS
  Nen tang: ASP.NET Core MVC & Microsoft SQL Server
  Huong dan su dung:
    1. Mo file nay trong SQL Server Management Studio (SSMS) hoac Azure Data Studio.
    2. Nhan Execute (F5) de tu dong tao Database [CGV_Cinemas_Db], bang va nap toan bo du lieu.
    3. Cau hinh chuoi ket noi trong appsettings.json:
       Server=(localdb)\mssqllocaldb;Database=CGV_Cinemas_Db;Trusted_Connection=True;MultipleActiveResultSets=true
====================================================================================================
*/

USE [master];
GO

IF NOT EXISTS (SELECT name FROM sys.databases WHERE name = N'CGV_Cinemas_Db')
BEGIN
    CREATE DATABASE [CGV_Cinemas_Db]
    COLLATE SQL_Latin1_General_CP1_CI_AS;
END
GO

USE [CGV_Cinemas_Db];
GO

-- ====================================================================================
-- PHAN 1: TAO CAU TRUC BANG (SCHEMA DDL)
-- ====================================================================================
CREATE TABLE [AspNetRoles] (
    [Id] nvarchar(450) NOT NULL,
    [Name] nvarchar(256) NULL,
    [NormalizedName] nvarchar(256) NULL,
    [ConcurrencyStamp] nvarchar(max) NULL,
    CONSTRAINT [PK_AspNetRoles] PRIMARY KEY ([Id])
);
GO


CREATE TABLE [AspNetUsers] (
    [Id] nvarchar(450) NOT NULL,
    [FullName] nvarchar(max) NOT NULL,
    [DateOfBirth] datetime2 NULL,
    [City] nvarchar(max) NULL,
    [FavoriteCinema] nvarchar(max) NULL,
    [MemberTier] nvarchar(max) NOT NULL,
    [RewardPoints] int NOT NULL,
    [CreatedAt] datetime2 NOT NULL,
    [UserName] nvarchar(256) NULL,
    [NormalizedUserName] nvarchar(256) NULL,
    [Email] nvarchar(256) NULL,
    [NormalizedEmail] nvarchar(256) NULL,
    [EmailConfirmed] bit NOT NULL,
    [PasswordHash] nvarchar(max) NULL,
    [SecurityStamp] nvarchar(max) NULL,
    [ConcurrencyStamp] nvarchar(max) NULL,
    [PhoneNumber] nvarchar(max) NULL,
    [PhoneNumberConfirmed] bit NOT NULL,
    [TwoFactorEnabled] bit NOT NULL,
    [LockoutEnd] datetimeoffset NULL,
    [LockoutEnabled] bit NOT NULL,
    [AccessFailedCount] int NOT NULL,
    CONSTRAINT [PK_AspNetUsers] PRIMARY KEY ([Id])
);
GO


CREATE TABLE [Cinemas] (
    [Id] int NOT NULL IDENTITY,
    [Name] nvarchar(max) NOT NULL,
    [City] nvarchar(max) NOT NULL,
    [Address] nvarchar(max) NOT NULL,
    [Hotline] nvarchar(max) NOT NULL,
    [ImageUrl] nvarchar(max) NULL,
    [Description] nvarchar(max) NULL,
    CONSTRAINT [PK_Cinemas] PRIMARY KEY ([Id])
);
GO


CREATE TABLE [FoodItems] (
    [Id] int NOT NULL IDENTITY,
    [Name] nvarchar(max) NOT NULL,
    [Category] nvarchar(max) NOT NULL,
    [Price] decimal(18,2) NOT NULL,
    [ImageUrl] nvarchar(max) NULL,
    [Description] nvarchar(max) NULL,
    [IsAvailable] bit NOT NULL,
    [SortOrder] int NOT NULL,
    CONSTRAINT [PK_FoodItems] PRIMARY KEY ([Id])
);
GO


CREATE TABLE [Movies] (
    [Id] int NOT NULL IDENTITY,
    [Title] nvarchar(max) NOT NULL,
    [Genre] nvarchar(max) NOT NULL,
    [Duration] int NOT NULL,
    [Rating] nvarchar(max) NOT NULL,
    [RatingColor] nvarchar(max) NOT NULL,
    [ReleaseDate] datetime2 NOT NULL,
    [EndDate] datetime2 NULL,
    [PosterUrl] nvarchar(max) NOT NULL,
    [BannerUrl] nvarchar(max) NULL,
    [TrailerUrl] nvarchar(max) NULL,
    [Director] nvarchar(max) NULL,
    [Cast] nvarchar(max) NULL,
    [Language] nvarchar(max) NULL,
    [Formats] nvarchar(max) NULL,
    [Synopsis] nvarchar(max) NULL,
    [IsNowShowing] bit NOT NULL,
    [IsUpcoming] bit NOT NULL,
    [Rank] int NULL,
    [SpecialTag] nvarchar(max) NULL,
    CONSTRAINT [PK_Movies] PRIMARY KEY ([Id])
);
GO


CREATE TABLE [AspNetRoleClaims] (
    [Id] int NOT NULL IDENTITY,
    [RoleId] nvarchar(450) NOT NULL,
    [ClaimType] nvarchar(max) NULL,
    [ClaimValue] nvarchar(max) NULL,
    CONSTRAINT [PK_AspNetRoleClaims] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_AspNetRoleClaims_AspNetRoles_RoleId] FOREIGN KEY ([RoleId]) REFERENCES [AspNetRoles] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [AspNetUserClaims] (
    [Id] int NOT NULL IDENTITY,
    [UserId] nvarchar(450) NOT NULL,
    [ClaimType] nvarchar(max) NULL,
    [ClaimValue] nvarchar(max) NULL,
    CONSTRAINT [PK_AspNetUserClaims] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_AspNetUserClaims_AspNetUsers_UserId] FOREIGN KEY ([UserId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [AspNetUserLogins] (
    [LoginProvider] nvarchar(450) NOT NULL,
    [ProviderKey] nvarchar(450) NOT NULL,
    [ProviderDisplayName] nvarchar(max) NULL,
    [UserId] nvarchar(450) NOT NULL,
    CONSTRAINT [PK_AspNetUserLogins] PRIMARY KEY ([LoginProvider], [ProviderKey]),
    CONSTRAINT [FK_AspNetUserLogins_AspNetUsers_UserId] FOREIGN KEY ([UserId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [AspNetUserRoles] (
    [UserId] nvarchar(450) NOT NULL,
    [RoleId] nvarchar(450) NOT NULL,
    CONSTRAINT [PK_AspNetUserRoles] PRIMARY KEY ([UserId], [RoleId]),
    CONSTRAINT [FK_AspNetUserRoles_AspNetRoles_RoleId] FOREIGN KEY ([RoleId]) REFERENCES [AspNetRoles] ([Id]) ON DELETE CASCADE,
    CONSTRAINT [FK_AspNetUserRoles_AspNetUsers_UserId] FOREIGN KEY ([UserId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [AspNetUserTokens] (
    [UserId] nvarchar(450) NOT NULL,
    [LoginProvider] nvarchar(450) NOT NULL,
    [Name] nvarchar(450) NOT NULL,
    [Value] nvarchar(max) NULL,
    CONSTRAINT [PK_AspNetUserTokens] PRIMARY KEY ([UserId], [LoginProvider], [Name]),
    CONSTRAINT [FK_AspNetUserTokens_AspNetUsers_UserId] FOREIGN KEY ([UserId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [ContactInquiries] (
    [Id] int NOT NULL IDENTITY,
    [FullName] nvarchar(max) NOT NULL,
    [Email] nvarchar(max) NOT NULL,
    [PhoneNumber] nvarchar(max) NULL,
    [Subject] nvarchar(max) NOT NULL,
    [Message] nvarchar(max) NOT NULL,
    [CreatedAt] datetime2 NOT NULL,
    [Status] nvarchar(max) NOT NULL,
    [AdminNotes] nvarchar(max) NULL,
    [UserId] nvarchar(450) NULL,
    CONSTRAINT [PK_ContactInquiries] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_ContactInquiries_AspNetUsers_UserId] FOREIGN KEY ([UserId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE SET NULL
);
GO


CREATE TABLE [CinemaHalls] (
    [Id] int NOT NULL IDENTITY,
    [CinemaId] int NOT NULL,
    [Name] nvarchar(max) NOT NULL,
    [HallType] nvarchar(max) NOT NULL,
    [TotalSeats] int NOT NULL,
    CONSTRAINT [PK_CinemaHalls] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_CinemaHalls_Cinemas_CinemaId] FOREIGN KEY ([CinemaId]) REFERENCES [Cinemas] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [HallRentalRequests] (
    [Id] int NOT NULL IDENTITY,
    [FullName] nvarchar(max) NOT NULL,
    [CompanyName] nvarchar(max) NULL,
    [Email] nvarchar(max) NOT NULL,
    [PhoneNumber] nvarchar(max) NOT NULL,
    [CinemaName] nvarchar(max) NOT NULL,
    [CinemaId] int NULL,
    [UserId] nvarchar(450) NULL,
    [ExpectedDate] datetime2 NULL,
    [GuestCount] int NOT NULL,
    [ServiceType] nvarchar(max) NOT NULL,
    [Notes] nvarchar(max) NULL,
    [CreatedAt] datetime2 NOT NULL,
    [Status] nvarchar(max) NOT NULL,
    CONSTRAINT [PK_HallRentalRequests] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_HallRentalRequests_AspNetUsers_UserId] FOREIGN KEY ([UserId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE SET NULL,
    CONSTRAINT [FK_HallRentalRequests_Cinemas_CinemaId] FOREIGN KEY ([CinemaId]) REFERENCES [Cinemas] ([Id]) ON DELETE SET NULL
);
GO


CREATE TABLE [NewsOffers] (
    [Id] int NOT NULL IDENTITY,
    [Title] nvarchar(max) NOT NULL,
    [Category] nvarchar(max) NOT NULL,
    [CategoryLabel] nvarchar(max) NOT NULL,
    [DateRange] nvarchar(max) NOT NULL,
    [ImageUrl] nvarchar(max) NOT NULL,
    [Summary] nvarchar(max) NOT NULL,
    [Content] nvarchar(max) NULL,
    [IsActive] bit NOT NULL,
    [CreatedAt] datetime2 NOT NULL,
    [MovieId] int NULL,
    [CinemaId] int NULL,
    [AuthorId] nvarchar(450) NULL,
    CONSTRAINT [PK_NewsOffers] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_NewsOffers_AspNetUsers_AuthorId] FOREIGN KEY ([AuthorId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE SET NULL,
    CONSTRAINT [FK_NewsOffers_Cinemas_CinemaId] FOREIGN KEY ([CinemaId]) REFERENCES [Cinemas] ([Id]) ON DELETE SET NULL,
    CONSTRAINT [FK_NewsOffers_Movies_MovieId] FOREIGN KEY ([MovieId]) REFERENCES [Movies] ([Id]) ON DELETE SET NULL
);
GO


CREATE TABLE [Seats] (
    [Id] int NOT NULL IDENTITY,
    [CinemaHallId] int NOT NULL,
    [Row] nvarchar(max) NOT NULL,
    [Number] int NOT NULL,
    [SeatCode] nvarchar(max) NOT NULL,
    [SeatType] nvarchar(max) NOT NULL,
    [PriceModifier] decimal(18,2) NOT NULL,
    CONSTRAINT [PK_Seats] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_Seats_CinemaHalls_CinemaHallId] FOREIGN KEY ([CinemaHallId]) REFERENCES [CinemaHalls] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [Showtimes] (
    [Id] int NOT NULL IDENTITY,
    [MovieId] int NOT NULL,
    [CinemaHallId] int NOT NULL,
    [StartTime] datetime2 NOT NULL,
    [EndTime] datetime2 NOT NULL,
    [Price] decimal(18,2) NOT NULL,
    [Format] nvarchar(max) NOT NULL,
    [CinemaId] int NULL,
    CONSTRAINT [PK_Showtimes] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_Showtimes_CinemaHalls_CinemaHallId] FOREIGN KEY ([CinemaHallId]) REFERENCES [CinemaHalls] ([Id]) ON DELETE CASCADE,
    CONSTRAINT [FK_Showtimes_Cinemas_CinemaId] FOREIGN KEY ([CinemaId]) REFERENCES [Cinemas] ([Id]),
    CONSTRAINT [FK_Showtimes_Movies_MovieId] FOREIGN KEY ([MovieId]) REFERENCES [Movies] ([Id]) ON DELETE CASCADE
);
GO


CREATE TABLE [Bookings] (
    [Id] int NOT NULL IDENTITY,
    [BookingCode] nvarchar(max) NOT NULL,
    [UserId] nvarchar(450) NULL,
    [CustomerName] nvarchar(max) NOT NULL,
    [CustomerEmail] nvarchar(max) NOT NULL,
    [CustomerPhone] nvarchar(max) NOT NULL,
    [ShowtimeId] int NOT NULL,
    [BookingDate] datetime2 NOT NULL,
    [SeatsList] nvarchar(max) NOT NULL,
    [TotalAmount] decimal(18,2) NOT NULL,
    [Status] nvarchar(max) NOT NULL,
    [PaymentMethod] nvarchar(max) NOT NULL,
    CONSTRAINT [PK_Bookings] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_Bookings_AspNetUsers_UserId] FOREIGN KEY ([UserId]) REFERENCES [AspNetUsers] ([Id]) ON DELETE SET NULL,
    CONSTRAINT [FK_Bookings_Showtimes_ShowtimeId] FOREIGN KEY ([ShowtimeId]) REFERENCES [Showtimes] ([Id]) ON DELETE NO ACTION
);
GO


CREATE TABLE [BookingFoodItems] (
    [Id] int NOT NULL IDENTITY,
    [BookingId] int NOT NULL,
    [FoodItemId] int NOT NULL,
    [Quantity] int NOT NULL,
    [UnitPrice] decimal(18,2) NOT NULL,
    CONSTRAINT [PK_BookingFoodItems] PRIMARY KEY ([Id]),
    CONSTRAINT [FK_BookingFoodItems_Bookings_BookingId] FOREIGN KEY ([BookingId]) REFERENCES [Bookings] ([Id]) ON DELETE CASCADE,
    CONSTRAINT [FK_BookingFoodItems_FoodItems_FoodItemId] FOREIGN KEY ([FoodItemId]) REFERENCES [FoodItems] ([Id]) ON DELETE NO ACTION
);
GO


CREATE INDEX [IX_AspNetRoleClaims_RoleId] ON [AspNetRoleClaims] ([RoleId]);
GO


CREATE UNIQUE INDEX [RoleNameIndex] ON [AspNetRoles] ([NormalizedName]) WHERE [NormalizedName] IS NOT NULL;
GO


CREATE INDEX [IX_AspNetUserClaims_UserId] ON [AspNetUserClaims] ([UserId]);
GO


CREATE INDEX [IX_AspNetUserLogins_UserId] ON [AspNetUserLogins] ([UserId]);
GO


CREATE INDEX [IX_AspNetUserRoles_RoleId] ON [AspNetUserRoles] ([RoleId]);
GO


CREATE INDEX [EmailIndex] ON [AspNetUsers] ([NormalizedEmail]);
GO


CREATE UNIQUE INDEX [UserNameIndex] ON [AspNetUsers] ([NormalizedUserName]) WHERE [NormalizedUserName] IS NOT NULL;
GO


CREATE INDEX [IX_BookingFoodItems_BookingId] ON [BookingFoodItems] ([BookingId]);
GO


CREATE INDEX [IX_BookingFoodItems_FoodItemId] ON [BookingFoodItems] ([FoodItemId]);
GO


CREATE INDEX [IX_Bookings_ShowtimeId] ON [Bookings] ([ShowtimeId]);
GO


CREATE INDEX [IX_Bookings_UserId] ON [Bookings] ([UserId]);
GO


CREATE INDEX [IX_CinemaHalls_CinemaId] ON [CinemaHalls] ([CinemaId]);
GO


CREATE INDEX [IX_ContactInquiries_UserId] ON [ContactInquiries] ([UserId]);
GO


CREATE INDEX [IX_HallRentalRequests_CinemaId] ON [HallRentalRequests] ([CinemaId]);
GO


CREATE INDEX [IX_HallRentalRequests_UserId] ON [HallRentalRequests] ([UserId]);
GO


CREATE INDEX [IX_NewsOffers_AuthorId] ON [NewsOffers] ([AuthorId]);
GO


CREATE INDEX [IX_NewsOffers_CinemaId] ON [NewsOffers] ([CinemaId]);
GO


CREATE INDEX [IX_NewsOffers_MovieId] ON [NewsOffers] ([MovieId]);
GO


CREATE INDEX [IX_Seats_CinemaHallId] ON [Seats] ([CinemaHallId]);
GO


CREATE INDEX [IX_Showtimes_CinemaHallId] ON [Showtimes] ([CinemaHallId]);
GO


CREATE INDEX [IX_Showtimes_CinemaId] ON [Showtimes] ([CinemaId]);
GO


CREATE INDEX [IX_Showtimes_MovieId] ON [Showtimes] ([MovieId]);
GO




