-- ====================================================================================
-- PHAN 3: KIEM TRA TONG SO BAN GHI
-- ====================================================================================
PRINT N'==> KHOI TAO CSDL VA DU LIEU CGV CINEMAS THANH CONG!';

SELECT
    t.name AS [TableName],
    p.rows AS [TotalRows]
FROM sys.tables t
INNER JOIN sys.partitions p ON t.object_id = p.object_id
WHERE p.index_id IN (0,1)
ORDER BY t.name;
GO
