INSERT INTO [Movies] ([Id], [Title], [Genre], [Duration], [Rating], [RatingColor], [ReleaseDate], [EndDate], [PosterUrl], [BannerUrl], [TrailerUrl], [Director], [Cast], [Language], [Formats], [Synopsis], [IsNowShowing], [IsUpcoming], [Rank], [SpecialTag]) VALUES (1, N'Lật Mặt 7: Một Điều Ước', N'Gia đình, Tâm lý', 121, N'T16', N'#2e7d32', '2026-04-26 00:00:00.000', '2026-09-30 00:00:00.000', N'https://images.unsplash.com/photo-1568038479111-87bf80659645?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=400', N'https://images.unsplash.com/photo-1440404653325-ab127d49abc1?crop=entropy&cs=tinysrgb&fit=max&fm=jpg&w=1200', N'https://www.youtube.com/watch?v=dQw4w9WgXcQ', N'Lý Hải', N'Thanh Hiền, Trương Minh Cường, Đinh Y Nhung, Quách Ngọc Tuyên, Trâm Anh', N'Tiếng Việt - Phụ đề Tiếng Anh', N'2D DIGITAL, IMAX', N'Câu chuyện cảm động về một người mẹ đơn thân tảo tần nuôi dạy 5 người con khôn lớn. Khi bà gặp tai nạn và già yếu, câu hỏi ai sẽ là người chăm sóc mẹ trở thành nỗi trăn trở sâu sắc của từng gia đình nhỏ.', 1, 0, 1, NULL);
