INSERT INTO [NewsOffers] ([Id], [Title], [Category], [CategoryLabel], [DateRange], [ImageUrl], [Summary], [Content], [IsActive], [CreatedAt], [MovieId], [CinemaId], [AuthorId]) VALUES (1, N'CGVXCOCA-COLA: DOUBLE DEAL – NHÂN ĐÔI BẮP NƯỚC', N'offers', N'ƯU ĐÃI', N'18/09/2026 - 01/10/2026', N'https://images.unsplash.com/photo-1568702846914-96b305d2aaeb?w=600&q=80', N'Chỉ 249K mà có tới 5 món và tặng thêm bắp nước?! Mua DOUBLE DEAL COMBO ngay hôm nay tại CGV!', N'Chương trình áp dụng tại tất cả các cụm rạp CGV trên toàn quốc khi mua combo đôi bắp nước cùng vé xem phim.', 1, '2026-10-14 08:05:17.161', NULL, NULL, N'57d57d5e-c022-4c1e-8414-739ff365851d');
INSERT INTO [NewsOffers] ([Id], [Title], [Category], [CategoryLabel], [DateRange], [ImageUrl], [Summary], [Content], [IsActive], [CreatedAt], [MovieId], [CinemaId], [AuthorId]) VALUES (2, N'SƯU TẬP 5 MẢNH KÝ ỨC ENDGAME – TẶNG 1 POSTER', N'news', N'TIN MỚI', N'24/09/2026 - 02/10/2026', N'https://images.unsplash.com/photo-1635805737707-575885ab0820?w=600&q=80', N'Sưu tập 5 mảnh ký ức Avengers Endgame và nhận ngay 1 Poster siêu to khổng lồ bản giới hạn – chỉ có tại CGV!', N'Khách hàng mua vé xem phim IMAX hoặc mua combo đặc biệt sẽ nhận được 1 mảnh ghép. Thu thập đủ 5 mảnh đổi quà tại quầy vé.', 1, '2026-10-14 08:05:17.161', NULL, NULL, N'57d57d5e-c022-4c1e-8414-739ff365851d');
INSERT INTO [NewsOffers] ([Id], [Title], [Category], [CategoryLabel], [DateRange], [ImageUrl], [Summary], [Content], [IsActive], [CreatedAt], [MovieId], [CinemaId], [AuthorId]) VALUES (3, N'CGV MEMBER DAY – COUPON GIẢM 99.000Đ', N'member', N'THÀNH VIÊN', N'Thứ Tư hàng tuần', N'https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=600&q=80', N'X2 điểm thưởng và nhận Coupon giảm 99.000đ dành riêng cho thành viên CGV trong ngày Member Day.', N'Dành riêng cho thành viên có thẻ CGV VIP và VVIP. Đăng nhập để nhận mã quà tặng ngay trên ứng dụng.', 1, '2026-10-14 08:05:17.161', NULL, 1, N'57d57d5e-c022-4c1e-8414-739ff365851d');
INSERT INTO [NewsOffers] ([Id], [Title], [Category], [CategoryLabel], [DateRange], [ImageUrl], [Summary], [Content], [IsActive], [CreatedAt], [MovieId], [CinemaId], [AuthorId]) VALUES (4, N'BÁNH TRÁNG TRỘN – SẢN PHẨM MỚI CHỈ 25.000Đ', N'news', N'TIN MỚI', N'Đang áp dụng', N'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=600&q=80', N'Cine De Chef ra mắt sản phẩm mới – Bánh Tráng Trộn với nhiều vị: Rong Biển, Mala, Tê Cay chỉ 25.000đ.', N'Thưởng thức món ăn vặt quốc dân ngay trong rạp chiếu phim với tiêu chuẩn vệ sinh an toàn thực phẩm hàng đầu.', 1, '2026-10-14 08:05:17.161', NULL, NULL, N'57d57d5e-c022-4c1e-8414-739ff365851d');
INSERT INTO [NewsOffers] ([Id], [Title], [Category], [CategoryLabel], [DateRange], [ImageUrl], [Summary], [Content], [IsActive], [CreatedAt], [MovieId], [CinemaId], [AuthorId]) VALUES (5, N'🎉 THỨ TƯ VUI VẺ - VÉ ĐỒNG GIÁ TỪ 65K TẠI CGV TOÀN QUỐC', N'offers', N'ƯU ĐÃI', N'Đến hết 31/12/2026', N'https://images.unsplash.com/photo-1517604931442-7e0c8ed2963c?w=600', N'Thứ Tư hàng tuần, xem phim thả ga với giá vé chỉ từ 65.000đ cho mọi lứa tuổi và tất cả các suất chiếu.', N'Áp dụng cho mọi suất chiếu 2D vào ngày Thứ Tư tại tất cả các cụm rạp CGV trên toàn quốc.', 1, '2026-10-14 08:05:17.161', NULL, NULL, N'57d57d5e-c022-4c1e-8414-739ff365851d');
INSERT INTO [ContactInquiries] ([Id], [FullName], [Email], [PhoneNumber], [Subject], [Message], [CreatedAt], [Status], [AdminNotes], [UserId]) VALUES (1, N'Nguyễn Văn An', N'an.nguyen@gmail.com', N'0988123456', N'Hỏi về đặt vé nhóm 50 người tại CGV Landmark 81', N'Công ty tôi có khoảng 50 nhân viên muốn đặt vé xem Lật Mặt 7 vào cuối tuần này. Nhờ CGV tư vấn báo giá và ưu đãi bắp nước.', '2026-10-14 07:35:17.244', N'Đã đọc', NULL, N'87f0967e-b0d8-4e97-b71f-188aa3881768');
INSERT INTO [ContactInquiries] ([Id], [FullName], [Email], [PhoneNumber], [Subject], [Message], [CreatedAt], [Status], [AdminNotes], [UserId]) VALUES (2, N'Phạm Thị Lan', N'lanpham@yahoo.com', N'0912345678', N'Góp ý về chất lượng âm thanh rạp chiếu số 3', N'Hôm qua mình xem suất chiếu 19h tại phòng 3, âm thanh loa vòm phía sau có tiếng rè nhỏ, mong ban quản lý kiểm tra lại thiết bị.', '2026-10-14 06:05:17.244', N'Đã đọc', NULL, NULL);
INSERT INTO [ContactInquiries] ([Id], [FullName], [Email], [PhoneNumber], [Subject], [Message], [CreatedAt], [Status], [AdminNotes], [UserId]) VALUES (3, N'Trần Thị Bích', N'bich.tran@outlook.com', N'0934567890', N'Thắc mắc về điểm tích lũy thẻ thành viên CGV VIP', N'Tôi vừa đổi thẻ sang hạng VIP nhưng chưa thấy số điểm thưởng sinh nhật tháng này được cộng vào tài khoản.', '2026-10-13 08:05:17.244', N'Đã đọc', N'Đã kiểm tra hệ thống, điểm thưởng sẽ tự động kích hoạt vào ngày đầu tháng sinh nhật của khách.', N'57d57d5e-c022-4c1e-8414-739ff365851d');
INSERT INTO [ContactInquiries] ([Id], [FullName], [Email], [PhoneNumber], [Subject], [Message], [CreatedAt], [Status], [AdminNotes], [UserId]) VALUES (4, N'Lê Minh Khoa', N'khoa.le@gmail.com', N'0977889900', N'Thuê trọn phòng chiếu L''Amour tổ chức sự kiện cầu hôn', N'Mình muốn thuê trọn phòng L''Amour Landmark 81 trong 2 tiếng để chiếu clip và cầu hôn bạn gái. Xin báo giá gói dịch vụ.', '2026-10-12 08:05:17.245', N'Đã phản hồi', N'Đã gọi điện tư vấn trực tiếp và gửi báo giá gói L''Amour Premium qua email.', NULL);
